470  template <typename Types, typename Extra>
   471  struct StateTable
   472  {
   473    typedef typename Types::HBUINT HBUINT;
   474    typedef typename Types::HBUSHORT HBUSHORT;
   475    typedef typename Types::ClassType ClassType;
   476
   477    enum State
   478    {
   479      STATE_START_OF_TEXT = 0,
   480      STATE_START_OF_LINE = 1,
   481    };
   482    enum Class
   483    {
   484      CLASS_END_OF_TEXT = 0,
   485      CLASS_OUT_OF_BOUNDS = 1,
   486      CLASS_DELETED_GLYPH = 2,
   487      CLASS_END_OF_LINE = 3,
   488    };
   489
   490    inline int new_state (unsigned int newState) const
   491    { return Types::extended ? newState : ((int) newState - (int) stateArrayTable) / nClasses; }
   492
   493    inline unsigned int get_class (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
   494    {
   495      if (unlikely (glyph_id == DELETED_GLYPH)) return CLASS_DELETED_GLYPH;
   496      return (this+classTable).get_class (glyph_id, num_glyphs, 1);
   497    }
   498
   499    inline const Entry<Extra> *get_entries () const
   500    {
   501      return (this+entryTable).arrayZ;
   502    }
   503
   504    inline const Entry<Extra> *get_entryZ (int state, unsigned int klass) const
   505    {
   506      if (unlikely (klass >= nClasses)) return nullptr;
   507
   508      const HBUSHORT *states = (this+stateArrayTable).arrayZ;
   509      const Entry<Extra> *entries = (this+entryTable).arrayZ;
   510
   511      unsigned int entry = states[state * nClasses + klass];
   512      DEBUG_MSG (APPLY, nullptr, "e%u", entry);
   513
   514      return &entries[entry];
   515    }
   516
   517    inline bool sanitize (hb_sanitize_context_t *c,
   518                          unsigned int *num_entries_out = nullptr) const
   519    {
   520      TRACE_SANITIZE (this);
   521      if (unlikely (!(c->check_struct (this) &&
   522                      classTable.sanitize (c, this)))) return_trace (false);
   523
   524      const HBUSHORT *states = (this+stateArrayTable).arrayZ;
   525      const Entry<Extra> *entries = (this+entryTable).arrayZ;
   526
   527      unsigned int num_classes = nClasses;
   528      if (unlikely (hb_unsigned_mul_overflows (num_classes, states[0].static_size)))
   529        return_trace (false);
   530      unsigned int row_stride = num_classes * states[0].static_size;
   531
   532      /* Apple 'kern' table has this peculiarity:
   533       *
   534       * "Because the stateTableOffset in the state table header is (strictly
   535       * speaking) redundant, some 'kern' tables use it to record an initial
   536       * state where that should not be StartOfText. To determine if this is
   537       * done, calculate what the stateTableOffset should be. If it's different
   538       * from the actual stateTableOffset, use it as the initial state."
   539       *
   540       * We implement this by calling the initial state zero, but allow *negative*
   541       * states if the start state indeed was not the first state.  Since the code
   542       * is shared, this will also apply to 'mort' table.  The 'kerx' / 'morx'
   543       * tables are not affected since those address states by index, not offset.
   544       */
   545
   546      int min_state = 0;
   547      int max_state = 0;
   548      unsigned int num_entries = 0;
   549
   550      int state_pos = 0;
   551      int state_neg = 0;
   552      unsigned int entry = 0;
   553      while (min_state < state_neg || state_pos <= max_state)
   554      {
   555        if (min_state < state_neg)
   556        {
   557          /* Negative states. */
   558          if (unlikely (hb_unsigned_mul_overflows (min_state, num_classes)))
   559            return_trace (false);
   560          if (unlikely (!c->check_array (&states[min_state * num_classes], -min_state, row_stride)))
   561            return_trace (false);
   562          if ((c->max_ops -= state_neg - min_state) < 0)
   563            return_trace (false);
   564          { /* Sweep new states. */
   565            const HBUSHORT *stop = &states[min_state * num_classes];
   566            if (unlikely (stop > states))
   567              return_trace (false);
   568            for (const HBUSHORT *p = states; stop < p; p--)
   569              num_entries = MAX<unsigned int> (num_entries, *(p - 1) + 1);
   570            state_neg = min_state;
   571          }
   572        }
   573
   574        if (state_pos <= max_state)
   575        {
   576          /* Positive states. */
   577          if (unlikely (!c->check_array (states, max_state + 1, row_stride)))
   578            return_trace (false);
   579          if ((c->max_ops -= max_state - state_pos + 1) < 0)
   580            return_trace (false);
   581          { /* Sweep new states. */
   582            if (unlikely (hb_unsigned_mul_overflows ((max_state + 1), num_classes)))
   583              return_trace (false);
   584            const HBUSHORT *stop = &states[(max_state + 1) * num_classes];
   585            if (unlikely (stop < states))
   586              return_trace (false);
   587            for (const HBUSHORT *p = &states[state_pos * num_classes]; p < stop; p++)
   588              num_entries = MAX<unsigned int> (num_entries, *p + 1);
   589            state_pos = max_state + 1;
   590          }
   591        }
   592
   593        if (unlikely (!c->check_array (entries, num_entries)))
   594          return_trace (false);
   595        if ((c->max_ops -= num_entries - entry) < 0)
   596          return_trace (false);
   597        { /* Sweep new entries. */
   598          const Entry<Extra> *stop = &entries[num_entries];
   599          for (const Entry<Extra> *p = &entries[entry]; p < stop; p++)
   600          {
   601            int newState = new_state (p->newState);
   602            min_state = MIN (min_state, newState);
   603            max_state = MAX (max_state, newState);
   604          }
   605          entry = num_entries;
   606        }
   607      }
   608
   609      if (num_entries_out)
   610        *num_entries_out = num_entries;
   720    inline void drive (context_t *c)
   721    {
   722      if (!c->in_place)
   723        buffer->clear_output ();
   724
   725      int state = StateTable<Types, EntryData>::STATE_START_OF_TEXT;
   726      bool last_was_dont_advance = false;
   727      for (buffer->idx = 0; buffer->successful;)
   728      {
   729        unsigned int klass = buffer->idx < buffer->len ?
   730                             machine.get_class (buffer->info[buffer->idx].codepoint, num_glyphs) :
   731                             (unsigned) StateTable<Types, EntryData>::CLASS_END_OF_TEXT;
   732        DEBUG_MSG (APPLY, nullptr, "c%u at %u", klass, buffer->idx);
   733        const Entry<EntryData> *entry = machine.get_entryZ (state, klass);
   734        if (unlikely (!entry))
   735          break;
   736
   737        /* Unsafe-to-break before this if not in state 0, as things might
   738         * go differently if we start from state 0 here.
   739         *
   740         * Ugh.  The indexing here is ugly... */
   741        if (state && buffer->backtrack_len () && buffer->idx < buffer->len)
   742        {
   743          /* If there's no action and we're just epsilon-transitioning to state 0,
   744           * safe to break. */
   745          if (c->is_actionable (this, entry) ||
   746              !(entry->newState == StateTable<Types, EntryData>::STATE_START_OF_TEXT &&
   747                entry->flags == context_t::DontAdvance))
   748            buffer->unsafe_to_break_from_outbuffer (buffer->backtrack_len () - 1, buffer->idx + 1);
   749        }
   750
   751        /* Unsafe-to-break if end-of-text would kick in here. */
   752        if (buffer->idx + 2 <= buffer->len)
   753        {
   754          const Entry<EntryData> *end_entry = machine.get_entryZ (state, 0);
   755          if (c->is_actionable (this, end_entry))
   756            buffer->unsafe_to_break (buffer->idx, buffer->idx + 2);
   757        }
   758
   759        if (unlikely (!c->transition (this, entry)))
   760          break;
   761
   762        last_was_dont_advance = (entry->flags & context_t::DontAdvance) && buffer->max_ops-- > 0;
   763
   764        state = machine.new_state (entry->newState);
   765        DEBUG_MSG (APPLY, nullptr, "s%d", state);
   766
   767        if (buffer->idx == buffer->len)
   768          break;
   769
   770        if (!last_was_dont_advance)
   771          buffer->next_glyph ();
   772      }
   773
   774      if (!c->in_place)
   775      {
   776        for (; buffer->successful && buffer->idx < buffer->len;)
   777          buffer->next_glyph ();
   778        buffer->swap_buffers ();
   779      }
   780    }
   781
   782    public:
   783    const StateTable<Types, EntryData> &machine;
   784    hb_buffer_t *buffer;
   785    unsigned int num_glyphs;
   786  };
